
.candidate {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
  padding: 8px 10px;
  border-bottom: 1px dashed var(--c-border);
  font-size: 12px;
  line-height: 1.5;
}

.candidate:last-child {
  border-bottom: none;
}

.candidate.empty {
  opacity: 0.5;
}

.c-name {
  font-weight: 700;
  font-size: 13px;
  color: var(--c-text);
}

.c-meta {
  font-size: 11px;
  color: var(--c-text-muted);
}

.c-look {
  color: var(--c-text);
}

.c-bg {
  color: var(--c-text-muted);
}

.c-select {
  margin-left: auto;
  padding: 2px 12px;
  border: 1px solid var(--c-primary-deep);
  border-radius: 10px;
  background: #fff;
  color: var(--c-primary-deep);
  font-family: inherit;
  font-size: 11px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.c-select:hover {
  background: var(--c-primary-deep);
  color: #fff;
}
